public void runProcess(SMHBookInventoryUpdationDataContract _dataContract)
{
    FTDBookTable book;
    Qty currentInventory;
    Qty newTransactionQtyNeeded;
    SMHBookInventoryTransaction inventoryTransaction;

    select firstonly book
        where book.Id == _dataContract.parmBookId();

    currentInventory = book.currentInventory();

    newTransactionQtyNeeded = _dataContract.parmNewQty() - currentInventory;

    inventoryTransaction.TransId = guid2Str(newGuid());
    inventoryTransaction.Book = book.RecId;
    inventoryTransaction.Qty = newTransactionQtyNeeded;

    if (inventoryTransaction.validateWrite())
    {
        inventoryTransaction.insert();
    }
    else
    {
        throw Exception::Error;
    }
}
